Here is the commit message:
iwlwifi: mvm: avoid possible access out of array.

The value in txq_id can be out of array scope,
validate it before accessing the array.

Signed-off-by: Mordechay Goodstein <mordechay.goodstein@intel.com>
Fixes: cf961e16620f ("iwlwifi: mvm: support dqa-mode agg on non-shared queue")
Signed-off-by: Luca Coelho <luciano.coelho@intel.com>

Here is the root cause:
The bug was caused by the potential for the `txq_id` variable to hold a value that exceeds the bounds of the `queue_info` array, leading to possible out-of-bounds access. This could occur if the `txq_id` was not properly validated before being used, especially in scenarios where the queue allocation failed or returned an invalid index. The lack of checks could result in accessing memory outside the allocated array, causing undefined behavior or crashes.

Here is the patch:

 int iwl_mvm_sta_tx_agg_start(struct iwl_mvm *mvm, struct ieee80211_vif *vif,
 			     struct ieee80211_sta *sta, u16 tid, u16 *ssn)
 {
 	struct iwl_mvm_sta *mvmsta = iwl_mvm_sta_from_mac80211(sta);
 	struct iwl_mvm_tid_data *tid_data;
 	u16 normalized_ssn;
-	int txq_id;
+	u16 txq_id;
 	int ret;

 	if (WARN_ON_ONCE(tid >= IWL_MAX_TID_COUNT))
 		return -EINVAL;

 	if (mvmsta->tid_data[tid].state != IWL_AGG_QUEUED &&
 	    mvmsta->tid_data[tid].state != IWL_AGG_OFF) {
 		IWL_ERR(mvm,
 			"Start AGG when state is not IWL_AGG_QUEUED or IWL_AGG_OFF %d!\n",
 			mvmsta->tid_data[tid].state);
 		return -ENXIO;
 	}

 	lockdep_assert_held(&mvm->mutex);

 	if (mvmsta->tid_data[tid].txq_id == IWL_MVM_INVALID_QUEUE &&
 	    iwl_mvm_has_new_tx_api(mvm)) {
 		u8 ac = tid_to_mac80211_ac[tid];

 		ret = iwl_mvm_sta_alloc_queue_tvqm(mvm, sta, ac, tid);
 		if (ret)
 			return ret;
 	}

 	spin_lock_bh(&mvmsta->lock);

 	/* possible race condition - we entered D0i3 while starting agg */
 	if (test_bit(IWL_MVM_STATUS_IN_D0I3, &mvm->status)) {
 		spin_unlock_bh(&mvmsta->lock);
 		IWL_ERR(mvm, "Entered D0i3 while starting Tx agg\n");
 		return -EIO;
 	}

 	/*
 	 * Note the possible cases:
 	 *  1. An enabled TXQ - TXQ needs to become agg'ed
 	 *  2. The TXQ hasn't yet been enabled, so find a free one and mark
 	 *	it as reserved
 	 */
 	txq_id = mvmsta->tid_data[tid].txq_id;
 	if (txq_id == IWL_MVM_INVALID_QUEUE) {
-		txq_id = iwl_mvm_find_free_queue(mvm, mvmsta->sta_id,
-						 IWL_MVM_DQA_MIN_DATA_QUEUE,
-						 IWL_MVM_DQA_MAX_DATA_QUEUE);
-		if (txq_id < 0) {
-			ret = txq_id;
+		ret = iwl_mvm_find_free_queue(mvm, mvmsta->sta_id,
+					      IWL_MVM_DQA_MIN_DATA_QUEUE,
+					      IWL_MVM_DQA_MAX_DATA_QUEUE);
+		if (ret < 0) {
 			IWL_ERR(mvm, "Failed to allocate agg queue\n");
 			goto out;
 		}

+		txq_id = ret;
+
 		/* TXQ hasn't yet been enabled, so mark it only as reserved */
 		mvm->queue_info[txq_id].status = IWL_MVM_QUEUE_RESERVED;
+	} else if (WARN_ON(txq_id >= IWL_MAX_HW_QUEUES)) {
+		ret = -ENXIO;
+		IWL_ERR(mvm, "tid_id %d out of range (0, %d)!\n",
+			tid, IWL_MAX_HW_QUEUES - 1);
+		goto out;
+
 	} else if (unlikely(mvm->queue_info[txq_id].status ==
 			    IWL_MVM_QUEUE_SHARED)) {
 		ret = -ENXIO;
 		IWL_DEBUG_TX_QUEUES(mvm,
 				    "Can't start tid %d agg on shared queue!\n",
 				    tid);
 		goto out;
 	}

 	IWL_DEBUG_TX_QUEUES(mvm,
 			    "AGG for tid %d will be on queue #%d\n",
 			    tid, txq_id);

 	tid_data = &mvmsta->tid_data[tid];
 	tid_data->ssn = IEEE80211_SEQ_TO_SN(tid_data->seq_number);
 	tid_data->txq_id = txq_id;
 	*ssn = tid_data->ssn;

 	IWL_DEBUG_TX_QUEUES(mvm,
 			    "Start AGG: sta %d tid %d queue %d - ssn = %d, next_recl = %d\n",
 			    mvmsta->sta_id, tid, txq_id, tid_data->ssn,
 			    tid_data->next_reclaimed);

 	/*
 	 * In 22000 HW, the next_reclaimed index is only 8 bit, so we'll need
 	 * to align the wrap around of ssn so we compare relevant values.
 	 */
 	normalized_ssn = tid_data->ssn;
 	if (mvm->trans->cfg->gen2)
 		normalized_ssn &= 0xff;

 	if (normalized_ssn == tid_data->next_reclaimed) {
 		tid_data->state = IWL_AGG_STARTING;
 		ieee80211_start_tx_ba_cb_irqsafe(vif, sta->addr, tid);
 	} else {
 		tid_data->state = IWL_EMPTYING_HW_QUEUE_ADDBA;
 	}

 	ret = 0;

 out:
 	spin_unlock_bh(&mvmsta->lock);

 	return ret;
 }



